"""Date-window membership for the date_window fixture."""

from __future__ import annotations

import datetime


def _parse_date(date_str: str) -> datetime.date:
    """Parse a date string in strict YYYY-MM-DD format, raising ValueError if invalid."""
    if not isinstance(date_str, str):
        raise ValueError(f"Expected a string, got {type(date_str)}")

    # Check strict format: must be exactly YYYY-MM-DD (10 chars)
    if len(date_str) != 10:
        raise ValueError(f"Invalid date format: {date_str!r}")

    if date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Invalid date format: {date_str!r}")

    year_str = date_str[0:4]
    month_str = date_str[5:7]
    day_str = date_str[8:10]

    # Ensure all parts are digits
    if not (year_str.isdigit() and month_str.isdigit() and day_str.isdigit()):
        raise ValueError(f"Invalid date format: {date_str!r}")

    # Ensure zero-padding by checking the string representation matches
    year = int(year_str)
    month = int(month_str)
    day = int(day_str)

    # Check that the original strings have correct zero-padding
    # (e.g. "2024-2-09" would fail the length check already, but be safe)
    if month_str != f"{month:02d}" or day_str != f"{day:02d}":
        raise ValueError(f"Invalid date format (missing zero padding): {date_str!r}")

    # Let datetime validate the actual calendar date (including leap years)
    try:
        return datetime.date(year, month, day)
    except ValueError as e:
        raise ValueError(f"Invalid calendar date: {date_str!r}") from e


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""
    # Parse and validate the target date
    target = _parse_date(target_date)

    for start_str, end_str in windows:
        start = _parse_date(start_str)
        end = _parse_date(end_str)

        if start > end:
            raise ValueError(
                f"Window start {start_str!r} is after end {end_str!r}"
            )

        # Inclusive on both boundaries
        if start <= target <= end:
            return True

    return False
